// Conservative, deterministic quantities: ambiguous source lines remain verbatim.
// No cooking instructions or shopping quantities are generated by a language model.
const numeric = '(?:\\d+(?:[.,]\\d+)?(?:\\s*\\/\\s*\\d+)?|[¼½¾⅓⅔])';
const prefix = new RegExp(`^(${numeric})(?:\\s*(?:à|a|–|-)\\s*(${numeric}))?\\s+(.+)$`, 'i');
const rangeAfterUnit = new RegExp(`^[àa–—-]\\s*${numeric}(?=\\s|[a-z]|$)`, 'i');
const fractions={'¼':.25,'½':.5,'¾':.75,'⅓':1/3,'⅔':2/3};
function number(text){
  if(text in fractions)return fractions[text];
  const [n,d]=text.replace(',','.').split('/').map(Number);
  return d===undefined?n:n/d;
}
const units = [
  [/^(?:c\.\s*à\s*(?:soupe|s\.)|cuillères? à soupe)\s+(?:de |d['’])?/i,'c. à soupe'],
  [/^(?:c\.\s*à\s*(?:café|c\.)|cuillères? à café)\s+(?:de |d['’])?/i,'c. à café'],
  [/^(kg|g|ml|cl|litres?|l)\s+(?:de |d['’])?/i,null],
];
const countable=/^(?:pincées?|gousses?|oignons?|carottes?|pommes?|patates?|courgettes?|poivrons?|œufs?|oeufs?|jaunes?|blancs?|pavés?|filets?|escalopes?|artichauts?|bananes?|tomates?|aubergines?|brocolis?|choux?|feuilles?|tortillas?|tranches?|poires?|pêches?|abricots?|citrons?|échalotes?)(?=\s|$)/i;
const normalize=s=>s.toLowerCase().replace(/[’]/g,"'").normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ').trim();
export function parseIngredient(raw){
  const text=raw.trim().replace(/(?<=\d),(?=\d)/g,'.');
  // Verified wording already used by the pilot; keep drained weight in the label.
  if(text==='65 g de pois chiches cuits en conserve, poids égoutté')return {min:65,max:65,unit:'g',label:'pois chiches cuits en conserve, poids égoutté'};
  if(text==='2 pavés de saumon (avec ou sans peau)')return {min:2,max:2,unit:'',label:'pavés de saumon (avec ou sans peau)'};
  if(text==='1 c. à café de paprika (ou épices au choix)')return {min:1,max:1,unit:'c. à café',label:'paprika (ou épices au choix)'};
  // Multi-ingredient lines, alternative quantities, packs, approximation and equipment need a human check.
  if(/[+,;()]|\b(?:ou|environ|optionnel|facultatif|filet d|poignée|noisette|moule|boîte|bloc|sachet)\b/i.test(text))return null;
  const m=text.match(prefix);if(!m)return null;
  const min=number(m[1]),max=m[2]?number(m[2]):min;
  if(!Number.isFinite(min)||!Number.isFinite(max)||min<=0||max<min)return null;
  const rest=m[3];let label=rest,unit='';
  for(const [pattern,name] of units){const u=rest.match(pattern);if(u){unit=name||u[1].toLowerCase().replace(/^litres?$/,'l');label=rest.slice(u[0].length);break;}}
  // A range with a unit on its first bound needs a manual quantity check.
  if(unit && rangeAfterUnit.test(label))return null;
  if(!label.trim()||(!unit&&!countable.test(rest)))return null;
  return {min,max,unit,label:label.trim()};
}
export function buildShoppingList(catalog,ids,people){
  if(!Number.isInteger(people)||people<1||people>12)throw Error('Choisissez entre 1 et 12 personnes.');
  const unique=[...new Set(ids)];if(unique.length>6)throw Error('Choisissez jusqu’à 6 recettes par menu.');
  const grouped=new Map();
  for(const id of unique){
    const recipe=catalog.find(r=>r.id===id);if(!recipe||!Number.isFinite(recipe.servings)||recipe.servings<=0)throw Error('Recette indisponible.');
    recipe.ingredients.forEach((raw,index)=>{
      const parsed=parseIngredient(raw);
      if(!parsed){
        const key=`source:${id}:${index}`;
        grouped.set(key,{key,kind:'source',text:raw,base:recipe.servings,sources:[{id,title:recipe.title}]});return;
      }
      // Merge only identical ingredient wording AND units. Never silently convert ml/g or different preparations.
      const key=`quantity:${normalize(parsed.label)}|${parsed.unit}`;
      const row=grouped.get(key)||{key,kind:'quantity',label:parsed.label,unit:parsed.unit,min:0,max:0,sources:[]};
      row.min+=parsed.min*people/recipe.servings;row.max+=parsed.max*people/recipe.servings;
      if(!row.sources.some(s=>s.id===id))row.sources.push({id,title:recipe.title});grouped.set(key,row);
    });
  }
  return [...grouped.values()];
}
const formatNumber=n=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:2}).format(n);
export function formatShoppingRow(row){
  if(row.kind==='source')return `${row.text} — quantité d’origine pour ${row.base} personne${row.base>1?'s':''}, à vérifier`;
  const amount=`${formatNumber(row.min)}${Math.abs(row.max-row.min)>1e-8?' à '+formatNumber(row.max):''}`;
  const preposition=/^(?:[aeiouyàâéèêîïôûœ]|huile)/i.test(row.label)?' d’':' de ';
  return `${amount}${row.unit?' '+row.unit+preposition: ' '}${row.label}`;
}
export function exportMenu(catalog,ids,people,owned=new Set()){
  const rows=buildShoppingList(catalog,ids,people).filter(row=>!owned.has(row.key));
  return ['Mon menu — Airfryer Gourmand',`${people} personne${people>1?'s':''} pour chaque recette`,'',
    ...[...new Set(ids)].map(id=>{const r=catalog.find(r=>r.id===id);return `${r.title}\nhttps://airfryergourmand.fr/recettes/${id==='poisson-pane-surgele'?'poisson-pane-surgele-air-fryer':id}/`;}),'','À prévoir',
    ...(rows.length?rows.map(row=>`☐ ${formatShoppingRow(row)}\n   Pour : ${row.sources.map(s=>s.title).join(' ; ')}`):['Tous les éléments sont cochés comme déjà disponibles.']),
    '', 'Quantités proportionnelles indicatives. Vérifiez les lignes conservées aux quantités d’origine, les options et la taille des ingrédients. Les temps de cuisson ne sont pas multipliés par le nombre de personnes. Prévoyez des fournées selon la capacité du panier.'].join('\n');
}
export function readMenuState(value,catalog){
  try{const state=JSON.parse(value);if(!Number.isInteger(state.people)||state.people<1||state.people>12||!Array.isArray(state.ids))return null;
    return {people:state.people,ids:[...new Set(state.ids.filter(id=>typeof id==='string'&&catalog.some(r=>r.id===id)))].slice(0,6)};
  }catch{return null;}
}
